import{_ as l,I as o,g as r,j as i}from"./chunks/framework.CjoWWfVe.js";const h=JSON.parse('{"title":"Логика учёта и работы","description":"Как устроен производственный конвейер в ОмниКрафт ЕРП, описание вкладок и страховка от забытых операций.","frontmatter":{"title":"Логика учёта и работы","description":"Как устроен производственный конвейер в ОмниКрафт ЕРП, описание вкладок и страховка от забытых операций.","order":2},"headers":[],"relativePath":"ru/docs/accounting-logic.md","filePath":"ru/docs/accounting-logic.md"}'),n={name:"ru/docs/accounting-logic.md"};function s(a,t,e,g,u,c){return o(),r("div",null,[...t[0]||(t[0]=[i('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="логика-учета-и-работы-в-программе" tabindex="-1">Логика учёта и работы в программе <a class="header-anchor" href="#логика-учета-и-работы-в-программе" aria-label="Permalink to &quot;Логика учёта и работы в программе&quot;">​</a></h1><p>Для комфортного ведения дела важно понимать внутреннюю логику учёта в ОмниКрафт ЕРП. Программа не просто хранит списки товаров — её учетный контур спроектирован как единый непрерывный поток, где физические материалы постепенно превращаются в готовую продукцию, а затем — в деньги.</p><hr><h2 id="🔄-единыи-производственныи-конвеиер-the-pipeline" tabindex="-1">🔄 Единый производственный конвейер (The Pipeline) <a class="header-anchor" href="#🔄-единыи-производственныи-конвеиер-the-pipeline" aria-label="Permalink to &quot;🔄 Единый производственный конвейер (The Pipeline)&quot;">​</a></h2><p>Вся логика взаимодействия разделов программы подчинена строгому экономическому циклу. Ресурсы последовательно перемещаются между вкладками в следующем порядке:</p><ul><li><strong>🛠️ Вкладка «Мастерская»</strong> — учет долгосрочного имущества (швейных машин, печей, компьютеров, инструментов) и расчет их износа. <ul><li><em>Износ (амортизация) переносится в накладные расходы... ⬇</em></li></ul></li><li><strong>📦 Вкладка «Сырьё»</strong> — склад материалов, закупки, средневзвешенные цены и автоматическое распределение логистики. <ul><li><em>Материалы идут в состав изделий... ⬇</em></li></ul></li><li><strong>🧮 Вкладка «Калькулятор»</strong> — создание рецептов, автоматический расчет себестоимости и рекомендуемой цены. <ul><li><em>Запуск партии в производство... ⬇</em></li></ul></li><li><strong>🔨 Вкладка «Производство» (Верстак)</strong> — очередь изготовления, планирование и ФИФО-резервы материалов. <ul><li><em>Выход готовой продукции на склад... ⬇</em></li></ul></li><li><strong>🛒 Вкладка «Товары»</strong> — склад готовых изделий (витрина). <ul><li><em>Факт продажи через выбранный канал... ⬇</em></li></ul></li><li><strong>🧾 Вкладка «Продажи»</strong> — управление каналами сбыта, наценки и чеки. <ul><li><em>Финансовые результаты записываются в отчетный блок... ⬇</em></li></ul></li><li><strong>📊 Вкладки «ДДС», «Капитал» и «Аналитика»</strong> — движение средств, результаты деятельности, капитализация и аналитика эффективности вашего бизнеса.</li></ul><hr><h3 id="подробныи-разбор-каждого-этапа" tabindex="-1">Подробный разбор каждого этапа: <a class="header-anchor" href="#подробныи-разбор-каждого-этапа" aria-label="Permalink to &quot;Подробный разбор каждого этапа:&quot;">​</a></h3><h4 id="_1-вкладка-«мастерская»" tabindex="-1">1. Вкладка «Мастерская» <a class="header-anchor" href="#_1-вкладка-«мастерская»" aria-label="Permalink to &quot;1. Вкладка «Мастерская»&quot;">​</a></h4><p>Здесь учитываются ваши долгосрочные ценности: станки, прессы, дорогие инструменты, купленная недвижимость.</p><ul><li><strong>Амортизация:</strong> Программа автоматически (в фоновом режиме) снижает стоимость оборудования каждый месяц в зависимости от его срока службы (при необходимости срок корректируется). Этот износ формирует накладные расходы, которые затем переносятся в себестоимость будущих изделий. Расходные материалы и мелкие инструменты (расходники) добавляются без срока службы и сразу автоматически учитываются в расходах.</li></ul><h4 id="_2-склад-сырья-вкладка-«сырье»" tabindex="-1">2. Склад сырья (Вкладка «Сырьё») <a class="header-anchor" href="#_2-склад-сырья-вкладка-«сырье»" aria-label="Permalink to &quot;2. Склад сырья (Вкладка «Сырьё»)&quot;">​</a></h4><p>Здесь хранится кожа, глина, дерево, фурнитура, клей и нитки.</p><ul><li><strong>Учет себестоимости (МАК):</strong> Программа считает средневзвешенную цену материалов. Если вы купили партию по одной цене, а через неделю по другой, система сама рассчитает среднюю стоимость остатка.</li><li><strong>Логистика:</strong> Затраты на доставку партии материалов автоматически распределяются на их себестоимость. Вам не нужно вручную высчитывать долю доставки для каждой пряжки или куска кожи.</li></ul><h4 id="_3-калькулятор-вкладка-«калькулятор»" tabindex="-1">3. Калькулятор (Вкладка «Калькулятор») <a class="header-anchor" href="#_3-калькулятор-вкладка-«калькулятор»" aria-label="Permalink to &quot;3. Калькулятор (Вкладка «Калькулятор»)&quot;">​</a></h4><p>Раздел создания рецептов (технологических карт) ваших изделий.</p><ul><li><strong>Расчет себестоимости:</strong> Калькулятор автоматически объединяет затраты на материалы (по текущей МАК-цене со склада), стоимость времени мастера и накладные расходы (включая амортизацию оборудования). На основе себестоимости и используемых наценок и прочих настроек программа рассчитывает рекомендуемую цену для каждого канала продаж.</li></ul><h4 id="_4-верстак-вкладка-«производство»" tabindex="-1">4. Верстак (Вкладка «Производство») <a class="header-anchor" href="#_4-верстак-вкладка-«производство»" aria-label="Permalink to &quot;4. Верстак (Вкладка «Производство»)&quot;">​</a></h4><p>План работы и динамическая очередь заказов.</p><ul><li><strong>Гибкое планирование без ограничений:</strong> Вам не нужно планировать каждое изделие строго перед началом работы. Вы можете накидать план производства на недели или месяц вперед, формируя комфортную очередь.</li><li><strong>Умное резервирование сырья (ФИФО):</strong> На складе не обязательно иметь материалы под весь созданный план. Программа автоматически анализирует очередь сверху вниз: она зарезервирует материалы под те позиции, на которые сырья хватает, и укажет на дефицит для изделий, под которые потребуется дозакупка. Это защищает склад от ухода в минус.</li><li><strong>Управление приоритетами и пауза:</strong> Вы можете в любой момент изменить приоритеты в очереди — переместить срочный заказ наверх или поставить какую-то позицию на паузу (переведя в черновик). Программа мгновенно пересчитает резервы материалов под новые приоритеты в реальном времени. Если под нижнюю позицию материалы есть, вы можете запустить её вперед, отложив дефицитную.</li><li><strong>Списание:</strong> Физическое списание сырья происходит только в момент, когда вы отмечаете изделие как готовое в программе.</li></ul><h4 id="_5-витрина-вкладка-«товары»" tabindex="-1">5. Витрина (Вкладка «Товары») <a class="header-anchor" href="#_5-витрина-вкладка-«товары»" aria-label="Permalink to &quot;5. Витрина (Вкладка «Товары»)&quot;">​</a></h4><p>Склад готовой продукции (ваша витрина).</p><ul><li><strong>Оценка склада:</strong> Изделия числятся на складе по их фактической себестоимости, рассчитанной в Калькуляторе.</li></ul><h4 id="_6-финансы-вкладки-«ддс»-«капитал»-и-«аналитика»" tabindex="-1">6. Финансы (Вкладки «ДДС», «Капитал» и «Аналитика») <a class="header-anchor" href="#_6-финансы-вкладки-«ддс»-«капитал»-и-«аналитика»" aria-label="Permalink to &quot;6. Финансы (Вкладки «ДДС», «Капитал» и «Аналитика»)&quot;">​</a></h4><p>Итоговая точка, где сходятся все потоки.</p><ul><li><strong>Регистрация сделки:</strong> При продаже изделия выручка (живые деньги) автоматически учитывается в приход ДДС, а само изделие физически списывается со склада готовой продукции.</li><li><strong>Расчет прибыли:</strong> Программа наглядно показывает разницу между доходами и затратами.</li><li><strong>Аналитика эффективности:</strong> Позволяет детально изучить процессы деятельности вашей мастерской, посмотреть динамику её развития и проанализировать рентабельность через множество полезных графиков и отчетов.</li></ul><hr><h2 id="📈-практическии-пример-от-вложении-до-чистои-прибыли" tabindex="-1">📈 Практический пример: От вложений до чистой прибыли <a class="header-anchor" href="#📈-практическии-пример-от-вложении-до-чистои-прибыли" aria-label="Permalink to &quot;📈 Практический пример: От вложений до чистой прибыли&quot;">​</a></h2><p>Давайте разберем реальный жизненный цикл ремесленного дела в программе — от стартовых закупок оборудования до окупаемости и первой прибыли.</p><blockquote><p><strong>Шаг 1. Стартовые вложения</strong> Вы инвестировали личные средства: купили профессиональное оборудование и базовые инструменты на <strong>150 000 ₽</strong>, а также партию материалов для производства на <strong>50 000 ₽</strong>. Дополнительно вы оплатили рекламу на первый месяц — <strong>10 000 ₽</strong>.</p><ul><li><em>Сальдо ДДС:</em> <strong>-210 000 ₽</strong> (общая сумма ваших личных вложений в запуск бизнеса).</li><li><em>Баланс (Активы):</em> <strong>200 000 ₽</strong> (стоимость оборудования и сырья). Обратите внимание: затраты на рекламу (10 000 ₽) списались как чистый расход и не увеличили стоимость имущества мастерской.</li></ul><p><strong>Шаг 2. Производство и маржинальные продажи</strong> Вы пустили в дело часть материалов на <strong>20 000 ₽</strong>, изготовили партию товаров и продали её за <strong>80 000 ₽</strong>. Выручка вернулась на вашу карту. Амортизация (износ) оборудования за этот период составила <strong>2 000 ₽</strong>. <em>(Примечание: свою зарплату как мастера вы решили не выделять отдельной ставкой, а заложили в итоговую наценку товара).</em></p><ul><li><em>Сальдо ДДС:</em> -210 000 ₽ + 80 000 ₽ = <strong>-130 000 ₽</strong>. Вы всё ещё в кассовом «минусе», так как бизнес пока не вернул вам все стартовые вложения.</li><li><em>Баланс (Активы):</em> Оборудование (уже 148 000 ₽ с учетом износа) + оставшиеся материалы (30 000 ₽) = <strong>178 000 ₽</strong>.</li><li><em>Вывод этапа:</em> Лично вы пока в минусе на 130 тысяч. Но ваша мастерская владеет реальными ценностями на 178 тысяч. Бизнес работает эффективно и постепенно возвращает ваши вложения.</li></ul><p><strong>Шаг 3. Полная окупаемость и выход в плюс</strong> Вы переработали оставшиеся материалы (на <strong>30 000 ₽</strong>) и продали готовую продукцию за <strong>150 000 ₽</strong>.</p><ul><li><em>Сальдо ДДС:</em> -130 000 ₽ + 150 000 ₽ = <strong>+20 000 ₽</strong>.</li><li><em>Баланс (Активы):</em> Оборудование (например, 145 000 ₽ с учетом дальнейшей амортизации) + материалы (<strong>0 ₽</strong>) = <strong>145 000 ₽</strong>.</li><li><em>Итоговый вывод:</em> Бизнес окупил вложения. Вы вернули себе вложенные 210 000 ₽. Теперь у вас есть <strong>20 000 ₽</strong> чистой денежной прибыли, а в мастерской по-прежнему работают ваши активы на <strong>145 000 ₽</strong>, готовые приносить прибыль дальше.</li></ul></blockquote><hr><h2 id="🛡️-физическая-инвентаризация-как-страховка-от-ошибок" tabindex="-1">🛡️ Физическая инвентаризация как страховка от ошибок <a class="header-anchor" href="#🛡️-физическая-инвентаризация-как-страховка-от-ошибок" aria-label="Permalink to &quot;🛡️ Физическая инвентаризация как страховка от ошибок&quot;">​</a></h2><p>В реальной работе легко забыть нажать кнопку в программе: не провести вовремя закупку, не списать готовый товар или забыть отметить продажу. В ОмниКрафт ЕРП главным страховочным механизмом от человеческого фактора является <strong>физическая инвентаризация</strong>.</p><p>Физический мир всегда честнее программы, поэтому любое забытое действие выявляется при сверке остатков:</p><ul><li><strong>Забыли провести закупку сырья?</strong> При инвентаризации склада сырья вы обнаружите реальные материалы на полке, которых нет в программе. Вы фиксируете излишек, и баланс сырья восстановится.</li><li><strong>Забыли отправить готовый товар на склад?</strong> При сверке готовых товаров вы увидите изделие на полке, которого «нет» на витрине в программе, но при этом на верстаке у вас будет висеть незавершенный заказ. Это напомнит вам завершить изготовление.</li><li><strong>Забыли отметить продажу изделия?</strong> Программа покажет, что в базе товар числится, а по факту его на полке нет. Обнаружив недостачу, вы вспомните о сделке и проведёте чек.</li></ul><div class="tip custom-block"><p class="custom-block-title">Настройка отображения даты</p><p>По умолчанию при проведении чека всегда проставляется текущая автоматическая дата. Чтобы поле выбора даты не отвлекало вас при ежедневных быстрых сделках, вы можете полностью отключить его показ в Настройках — программа будет оформлять продажи текущим днем. Если же вам потребуется провести крупную сделку прошлым числом, вы сможете временно включить поле даты, провести операцию в верном отчетном периоде и скрыть его обратно.</p></div><div class="warning custom-block"><p class="custom-block-title">Ограничения смешанных финансов и дисциплина учёта</p><p>Инвентаризация отлично страхует все материальные процессы (сырье, инструменты, готовые товары).</p><p>Однако помните: если вы ведете учет по умолчанию (в режиме смешанных финансов), <strong>нематериальные забытые расходы (например, реклама, подписки на сервисы, налоги) не застрахованы инвентаризацией</strong>. Если вы оплатили рекламу с личной карты и забыли внести это в программу — система не выдаст ошибку, так как у этих расходов нет физического воплощения на полке.</p><p>Здесь на первый план выходит <strong>личная дисциплина учёта</strong>. Чтобы графики рентабельности и аналитика эффективности оставались точными, важно выработать привычку сразу фиксировать любые безналичные и нематериальные траты, совершенные в интересах мастерской, а также своевременно вносить любые сторонние доходы, связанные с бизнесом, но не являющиеся доходами от реализации (например, чаевые или оплату за индивидуальные мастер-классы). Без регулярной дисциплины ввода таких показателей данные о реальной прибыли будут искажены.</p></div>',38)])])}const m=l(n,[["render",s]]);export{h as __pageData,m as default};
